    if (c >= 0x10000) {
      c -= 0x10000;
      out->units[out->length++] = (uint16_t)(0xD800 + (c >> 10));
      out->units[out->length++] = (uint16_t)(0xDC00 + (c & 0x3FF));
    } else {
      out->units[out->length++] = (uint16_t)c;
    }
  }
  return 1;
#endif
}

static ioi_string env_or_empty(const char *name) {
  ioi_string s;
  return env(name, &s) ? s : str_new(0);
}

/* A string of 1 to 18 decimal digits, or -1. */
static int64_t digits_value(ioi_string s) {
  if (!s.length || s.length > 18) return -1;
  int64_t value = 0;
  for (size_t i = 0; i < s.length; i++) {
    if (s.units[i] < '0' || s.units[i] > '9') return -1;
    value = value * 10 + (s.units[i] - '0');
  }
  return value;
}

static uint8_t *body;
static size_t body_length;
static int body_read;

/* The request body, read once from stdin: CONTENT_LENGTH bytes, or up to the end of input. */
static void read_body(void) {
  if (body_read) return;
  body_read = 1;
  ioi_string length_text = env_or_empty("CONTENT_LENGTH");
  int64_t length = digits_value(length_text);
  str_free(&length_text);
  size_t capacity = 64;
  body = checked(malloc(capacity));
  while (length < 0 || (int64_t)body_length < length) {
    int c = getchar();
    if (c == EOF) break;
    if (body_length == capacity) body = checked(realloc(body, capacity *= 2));
    body[body_length++] = (uint8_t)c;
  }
}

static uint16_t ascii_upper(uint16_t c) { return c >= 'a' && c <= 'z' ? c - 32 : c; }

static int is_blank(uint16_t c) { return c == ' ' || c == '\t'; }

/* A request header, as CGI passes it: HTTP_ and the name in capitals with - as _, except the two
 * it passes without the prefix. A name that isn't ASCII letters, digits, - and _ finds nothing. */
static int header(ioi_string name, ioi_string *out) {
  char key[256 + 6] = "HTTP_";
  if (name.length == 0 || name.length > 256) return 0;
  char *k = key + 5;
  for (size_t i = 0; i < name.length; i++) {
    uint16_t c = ascii_upper(name.units[i]);
    if (c == '-') c = '_';
    if (!((c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9') || c == '_')) return 0;
    k[i] = (char)c;
  }
  k[name.length] = 0;
  if (!strcmp(k, "CONTENT_TYPE") || !strcmp(k, "CONTENT_LENGTH")) return env(k, out);
  return env(key, out);
}

/* The units of [s] from [start] to [end], without spaces and tabs at either end. */
static ioi_string trimmed(ioi_string s, size_t start, size_t end) {
  while (start < end && is_blank(s.units[start])) start++;
  while (end > start && is_blank(s.units[end - 1])) end--;
  ioi_string out = str_new(end - start);
  memcpy(out.units, s.units + start, (end - start) * sizeof(uint16_t));
  out.length = end - start;
  return out;
}

static int cookie(ioi_string name, ioi_string *out) {
  ioi_string all = env_or_empty("HTTP_COOKIE");
  int found = 0;
  size_t start = 0;
  for (size_t i = 0; i <= all.length && !found; i++) {
    if (i < all.length && all.units[i] != ';') continue;
    for (size_t j = start; j < i; j++) {
      if (all.units[j] != '=') continue;
      ioi_string key = trimmed(all, start, j);
      if (str_equal(key, name)) {
        *out = trimmed(all, j + 1, i);
        found = 1;
      }
      str_free(&key);
      break;
    }
    start = i + 1;
  }
  str_free(&all);
  return found;
}

static int hex_digit(uint16_t c) {
  if (c >= '0' && c <= '9') return c - '0';
  if (c >= 'a' && c <= 'f') return c - 'a' + 10;
  if (c >= 'A' && c <= 'F') return c - 'A' + 10;
  return -1;
}

/* %XX is a byte and, with [plus], + is a space; then the bytes are decoded as str_decode does. */
static ioi_string url_decode(const uint8_t *bytes, size_t length, int plus) {
  uint8_t *out = checked(malloc(length + 1));
  size_t n = 0;
  for (size_t i = 0; i < length; i++) {
    int high = i + 2 < length ? hex_digit(bytes[i + 1]) : -1, low = i + 2 < length ? hex_digit(bytes[i + 2]) : -1;
    if (bytes[i] == '+' && plus) {
      out[n++] = ' ';
    } else if (bytes[i] == '%' && high >= 0 && low >= 0) {
      out[n++] = (uint8_t)(high * 16 + low);
      i += 2;
    } else {
      out[n++] = bytes[i];
    }
  }
  ioi_string s = str_decode(out, n);
  free(out);
  return s;
}

/* The first [name] in an application/x-www-form-urlencoded list of bytes, decoded. */
static int field(const uint8_t *encoded, size_t length, ioi_string name, ioi_string *out) {
  size_t start = 0;
  for (size_t i = 0; i <= length; i++) {
    if (i < length && encoded[i] != '&') continue;
    size_t equals = start;
    while (equals < i && encoded[equals] != '=') equals++;
    ioi_string key = url_decode(encoded + start, equals - start, 1);
    int match = str_equal(key, name);
    str_free(&key);
    if (match) {
      *out = equals < i ? url_decode(encoded + equals + 1, i - equals - 1, 1) : str_new(0);
      return 1;
    }
    start = i + 1;
  }
  return 0;
}

/* The body of a form post, or nothing (NULL) for any other kind of body. */
static const uint8_t *form(size_t *length) {
  ioi_string type = env_or_empty("CONTENT_TYPE");
  static const char form_type[] = "application/x-www-form-urlencoded";
  int is_form = type.length >= sizeof form_type - 1;
  for (size_t i = 0; is_form && i < sizeof form_type - 1; i++) {
    uint16_t c = type.units[i];
    is_form = (c >= 'A' && c <= 'Z' ? c + 32 : c) == form_type[i];
  }
  str_free(&type);
  *length = 0;
  if (!is_form) return NULL;
  read_body();
  *length = body_length;
  return body;
}

/* Stores a lookup's result: the string in [into] and status #1, or #2 when there is none. */
static void found(uint32_t status, uint32_t into, int was_found, ioi_string *value) {
  if (was_found) {
    ick_set_string(into, value->units, value->length);
    str_free(value);
  }
  ick_set_scalar(status, was_found ? 1 : 2);
}

/* ---- Strings in ;4400 and ;49221 (R5) ---------------------------------------------------- */

static ioi_string *params;
static size_t param_count;

typedef struct {
  uint64_t index;
  ioi_string value;
} ioi_arg;

static ioi_arg *args;
static size_t arg_count, arg_capacity;

/* ;4400 SUB n: a parameter the route doesn't have is E241. */
static ioi_string param(uint64_t n, uint32_t next) {
  if (n < 1 || n > param_count) ick_fatal(241, next);
  return str_copy(params[n - 1]);
}

/* ;49221 SUB n: one never stored is the empty string. */
static ioi_string arg(uint64_t n, uint32_t next) {
  if (n < 1 || n > 0xFFFFFFFFu) ick_fatal(241, next);
  for (size_t i = 0; i < arg_count; i++) {
    if (args[i].index == n) return str_copy(args[i].value);
  }
  return str_new(0);
}

/* Stores [value], which the arguments then own. */
static void set_arg(uint64_t n, ioi_string value, uint32_t next) {
  if (n < 1 || n > 0xFFFFFFFFu) ick_fatal(241, next);
  for (size_t i = 0; i < arg_count; i++) {
    if (args[i].index == n) {
      str_free(&args[i].value);
      args[i].value = value;
      return;
    }
  }
  if (arg_count == arg_capacity) {
    arg_capacity = arg_capacity ? arg_capacity * 2 : 8;
    args = checked(realloc(args, arg_capacity * sizeof *args));
  }
  args[arg_count++] = (ioi_arg){n, value};
}

static void set_string(uint32_t array, ioi_string value) {
  ick_set_string(array, value.units, value.length);
  str_free(&value);
}

/* ---- The response ------------------------------------------------------------------------ */

static uint64_t status = 200;
static int sent;

typedef struct {
  char *name, *value;
} ioi_header;

static ioi_header *headers;
static size_t header_count, header_capacity;

/* The status and headers can't change once the body has started (E823). */
static void unsent(uint32_t next) {
  if (sent) ick_fatal(823, next);
}

/* A header name is an HTTP token (RFC 9110). */
static int is_token(ioi_string s) {
  if (!s.length) return 0;
  for (size_t i = 0; i < s.length; i++) {
    uint16_t c = s.units[i];
    int ok = (c >= '0' && c <= '9') || (c >= 'A' && c <= 'Z') || (c >= 'a' && c <= 'z') ||
             (c < 0x80 && c && strchr("!#$%&'*+.^_`|~-", (char)c));
    if (!ok) return 0;
  }
  return 1;
}

/* A header value has no control characters but tabs, so it can't split the response. */
static int is_field_value(ioi_string s) {
  for (size_t i = 0; i < s.length; i++) {
    if ((s.units[i] < 0x20 && s.units[i] != '\t') || s.units[i] == 0x7F) return 0;
  }
  return 1;
}

/* RFC 6265's cookie-octet: ASCII with no controls, spaces, ", comma, ; or backslash, so a value
 * can't add attributes to its cookie. */
static int is_cookie_value(ioi_string s) {
  for (size_t i = 0; i < s.length; i++) {
    uint16_t c = s.units[i];
    if (!(c == 0x21 || (c >= 0x23 && c <= 0x2B) || (c >= 0x2D && c <= 0x3A) || (c >= 0x3C && c <= 0x5B) ||
          (c >= 0x5D && c <= 0x7E)))
      return 0;
  }
  return 1;
}

/* Adds a header that has been checked. The header takes the strings. */
static void add_header(ioi_string name, ioi_string value) {
  if (header_count == header_capacity) {
    header_capacity = header_capacity ? header_capacity * 2 : 8;
    headers = checked(realloc(headers, header_capacity * sizeof *headers));
  }
  headers[header_count++] = (ioi_header){str_utf8(name, NULL), str_utf8(value, NULL)};
  str_free(&name);
  str_free(&value);
}

static const char *reason(uint64_t code) {
  switch (code) {
  case 200: return "OK";
  case 201: return "Created";
  case 204: return "No Content";
  case 301: return "Moved Permanently";
  case 302: return "Found";
  case 303: return "See Other";
  case 304: return "Not Modified";
  case 307: return "Temporary Redirect";
  case 308: return "Permanent Redirect";
  case 400: return "Bad Request";
  case 401: return "Unauthorized";
  case 403: return "Forbidden";
  case 404: return "Not Found";
  case 405: return "Method Not Allowed";
  case 409: return "Conflict";
  case 410: return "Gone";
  case 418: return "I'm a teapot";
  case 422: return "Unprocessable Content";
  case 500: return "Internal Server Error";
  case 501: return "Not Implemented";
  case 503: return "Service Unavailable";
  default: return "Unknown";
  }
}

static int lower_equal(const char *a, const char *b) {
  for (; *a && *b; a++, b++) {
    char x = *a >= 'A' && *a <= 'Z' ? (char)(*a + 32) : *a;
    if (x != *b) return 0;
  }
  return !*a && !*b;
}

/* The CGI response's headers, before the first byte of its body (R2). */
static void prologue(void) {
  sent = 1;
  char line[64];
  int n = snprintf(line, sizeof line, "Status: %llu %s\n", (unsigned long long)status, reason(status));
  ick_output(line, (size_t)n);
  int typed = 0;
  for (size_t i = 0; i < header_count; i++) typed |= lower_equal(headers[i].name, "content-type");
  if (!typed) {
    static const char type[] = "Content-Type: text/html; charset=utf-8\n";
    ick_output(type, sizeof type - 1);
  }
  for (size_t i = 0; i < header_count; i++) {
    ick_output(headers[i].name, strlen(headers[i].name));
    ick_output(": ", 2);
    ick_output(headers[i].value, strlen(headers[i].value));
    ick_output("\n", 1);
  }
  ick_output("\n", 1);
}

/* ---- Templates (R6) ---------------------------------------------------------------------- */

typedef struct {
  char *bytes;
  size_t length, capacity;
} ioi_buffer;

static void put(ioi_buffer *b, const char *bytes, size_t length) {
  if (b->length + length > b->capacity) {
    while (b->length + length > b->capacity) b->capacity = b->capacity ? b->capacity * 2 : 256;
    b->bytes = checked(realloc(b->bytes, b->capacity));
  }
  memcpy(b->bytes + b->length, bytes, length);
  b->length += length;
}

static void put_text(ioi_buffer *b, const char *text) { put(b, text, strlen(text)); }

/* [s] as UTF-8, escaped for HTML unless [raw]; the buffer takes the string. */
static void put_html(ioi_buffer *b, ioi_string s, int raw) {
  size_t length;
  char *utf8 = str_utf8(s, &length);
  for (size_t i = 0; i < length; i++) {
    const char *entity = NULL;
    if (!raw) {
      switch (utf8[i]) {
      case '&': entity = "&amp;"; break;
      case '<': entity = "&lt;"; break;
      case '>': entity = "&gt;"; break;
      case '"': entity = "&quot;"; break;
      case '\'': entity = "&#39;"; break;
      }
    }
    if (entity) put_text(b, entity);
    else put(b, utf8 + i, 1);
  }
  free(utf8);
  str_free(&s);
}

/* A number as READ OUT's butchered Roman numeral. A letter under READ OUT's bar row (x1000) gets
 * text-decoration: overline, and one under its top row (x10^12, for 64-bit values) a border-top
 * line above that; in an attribute's value, where markup can't go, they are combining characters
 * instead, U+0305 and U+033F. Zero is an overlined no-break space. In wimp mode it is plain
 * decimal. */
static void put_numeral(ioi_buffer *b, uint64_t value, int attribute) {
  static const char *const opening[4] = {
      "", "<span style=\"text-decoration: overline\">", "<span style=\"border-top: 1px solid\">",
      "<span style=\"border-top: 1px solid\"><span style=\"text-decoration: overline\">"};
  static const char *const closing[4] = {"", "</span>", "</span>", "</span></span>"};
  char rows[3][96];
  int count = ick_numeral_rows(value, rows);
  if (count == 1) {
    put_text(b, rows[0]);
    return;
  }
  const char *letters = rows[count - 1], *bars = rows[count - 2], *top = count == 3 ? rows[0] : "";
  size_t width = strlen(letters);
  if (strlen(bars) > width) width = strlen(bars);
  if (strlen(top) > width) width = strlen(top);
  int run_style = -1;
  for (size_t c = 0; c < width; c++) {
    int barred = c < strlen(bars) && bars[c] == '_', topped = c < strlen(top) && top[c] == '_';
    int style = (topped ? 2 : 0) + (barred ? 1 : 0);
    if (!attribute && style != run_style) {
      if (run_style > 0) put_text(b, closing[run_style]);
      put_text(b, opening[style]);
      run_style = style;
    }
    if (c < strlen(letters)) put(b, letters + c, 1);
    else put_text(b, "\xC2\xA0");
    if (attribute && barred) put_text(b, "\xCC\x85");
    if (attribute && topped) put_text(b, "\xCC\xBF");
  }
  if (!attribute && run_style > 0) put_text(b, closing[run_style]);
}

/* READ OUT #n WITH TEMPLATE (R6): the template's pieces, with values from [values] (after the
 * template's number), written all at once. */
static void render(const ioi_template *t, const uint64_t *values, uint32_t next) {
  ioi_buffer b = {NULL, 0, 0};
  uint32_t v = 1;
  for (uint32_t i = 0; i < t->count; i++) {
    const ioi_piece *p = &t->pieces[i];
    switch (p->kind) {
    case 0: put(&b, p->text, p->length); break;
    case 1: put_html(&b, arg(p->index, next), p->raw); break;
    case 2: put_html(&b, param(values[v++], next), p->raw); break;
    case 3: put_html(&b, arg(values[v++], next), p->raw); break;
    default: put_numeral(&b, values[v++], p->attribute); break;
    }
  }
  if (b.length) ick_output(b.bytes, b.length);
  free(b.bytes);
}

/* ---- ActiveCassette (R7, Q95, Q99, Q119, Q145) -------------------------------------------- */

static const ioi_adapter *adapter;
static void *db;

/* Table and column names, by number from 1, read from the database when first needed. */
static ioi_strings tables;
static int tables_known;
static ioi_strings *columns; /* one list per table */
static int *columns_known;

/* What (16210) reports: rows the last read matched, or the last write changed. */
static int64_t last_count;

/* Writes ActiveCassette's reason to stderr, then raises [code]. */
static void cassette_fail(uint32_t code, const char *reason, uint32_t next) {
  fflush(stdout);
  fprintf(stderr, "ActiveCassette: %s\n", reason ? reason : "no reason given");
  fflush(stderr);
  ick_fatal(code, next);
}

static void forget_schema(void) {
  for (size_t i = 0; tables_known && i < tables.count; i++) strings_free(&columns[i]);
  strings_free(&tables);
  free(columns);
  free(columns_known);
  columns = NULL;
  columns_known = NULL;
  tables_known = 0;
}

static const ioi_adapter *load_adapter(const char *scheme, uint32_t next) {
  char name[12 + 64 + 1] = "IOI_ADAPTER_";
  size_t n = strlen(scheme);
  if (n > 64) cassette_fail(825, "the DATABASE_URL's scheme is too long", next);
  for (size_t i = 0; i <= n; i++) name[12 + i] = (char)(scheme[i] >= 'a' && scheme[i] <= 'z' ? scheme[i] - 32 : scheme[i]);
  ioi_string path;
  if (!env(name, &path)) {
    char reason[200];
    snprintf(reason, sizeof reason, "no adapter for %s: set %s to its library", scheme, name);
    cassette_fail(825, reason, next);
  }
  const ioi_adapter *(*entry)(void) = NULL;
#ifdef _WIN32
  wchar_t *wide = checked(malloc((path.length + 1) * sizeof(wchar_t)));
  for (size_t i = 0; i < path.length; i++) wide[i] = path.units[i];
  wide[path.length] = 0;
  HMODULE library = LoadLibraryW(wide);
  free(wide);
  if (library) entry = (const ioi_adapter *(*)(void))(void (*)(void))GetProcAddress(library, "ioi_adapter_entry");
#else
  char *file = str_utf8(path, NULL);
  void *library = dlopen(file, RTLD_NOW | RTLD_LOCAL);
  free(file);
  if (library) *(void **)&entry = dlsym(library, "ioi_adapter_entry");
#endif
  str_free(&path);
  if (!entry) cassette_fail(825, "the adapter's library can't be loaded, or has no ioi_adapter_entry", next);
  return entry();
}

/* Connects to DATABASE_URL (sqlite:./app.db when it isn't set), the first time a program needs to. */
static void cassette(uint32_t next) {
  if (db) return;
  ioi_string url_text;
  if (!env("DATABASE_URL", &url_text)) url_text = str_ascii("sqlite:./app.db");
  char *url = str_utf8(url_text, NULL);
  str_free(&url_text);
  char *colon = strchr(url, ':');
  if (!colon || colon == url) cassette_fail(825, "the DATABASE_URL has no scheme", next);
  *colon = 0;
  if (!strcmp(url, "sqlite")) {
    adapter = ioi_builtin_sqlite ? ioi_builtin_sqlite() : NULL;
    if (!adapter) cassette_fail(825, "this program has no SQLite", next);
  } else {
    adapter = load_adapter(url, next);
  }
  *colon = ':';
  if (!adapter || adapter->version != IOI_ADAPTER_VERSION) cassette_fail(825, "the adapter is not version 1", next);
  db = adapter->connect(url);
  if (!db) cassette_fail(825, adapter->error(NULL), next);
  free(url);
}

/* A column's value as a string: its digits for an integer, its text decoded, and nothing for NULL. */
static ioi_string value_string(ioi_value v) {
  if (v.kind == IOI_INTEGER) {
    char digits[24];
    snprintf(digits, sizeof digits, "%lld", (long long)v.integer);
    return str_ascii(digits);
  }
  if (v.kind == IOI_TEXT) return str_decode((const uint8_t *)v.text, v.length);
  return str_new(0);
}

/* Every row's first column, from rows the adapter gave (or E826). */
static ioi_strings first_columns(void *rows, uint32_t next) {
  if (!rows) cassette_fail(826, adapter->error(db), next);
  ioi_strings out = {NULL, 0};
  size_t capacity = 0;
  int status;
  while ((status = adapter->next(rows)) == 1) {
    if (out.count == capacity) {
      capacity = capacity ? capacity * 2 : 8;
      out.items = checked(realloc(out.items, capacity * sizeof(ioi_string)));
    }
    ioi_value v = {IOI_NULL, 0, NULL, 0};
    if (adapter->width(rows) > 0) adapter->column(rows, 0, &v);
    out.items[out.count++] = value_string(v);
  }
  if (status < 0) cassette_fail(826, adapter->error(db), next);
  adapter->finish(rows);
  return out;
}

static void know_tables(uint32_t next) {
  if (tables_known) return;
  tables = first_columns(adapter->tables(db), next);
  columns = checked(calloc(tables.count ? tables.count : 1, sizeof(ioi_strings)));
  columns_known = checked(calloc(tables.count ? tables.count : 1, sizeof(int)));
  tables_known = 1;
}

/* Table [t] (from 1): E824 past the end of the schema. */
static ioi_string table_name(uint64_t t, uint32_t next) {
  know_tables(next);
  if (t < 1 || t > tables.count) cassette_fail(824, "no such table", next);
  return tables.items[t - 1];
}

/* Column [c] (from 1) of table [t]: E824 past the end of the table. */
static ioi_string column_name(uint64_t t, uint64_t c, uint32_t next) {
  ioi_string table = table_name(t, next);
  if (!columns_known[t - 1]) {
    char *name = str_utf8(table, NULL);
    void *rows = adapter->columns(db, name);
    free(name);
    columns[t - 1] = first_columns(rows, next);
    columns_known[t - 1] = 1;
  }
  if (c < 1 || c > columns[t - 1].count) cassette_fail(824, "no such column", next);
  return columns[t - 1].items[c - 1];
}

/* A statement's SQL, being built. */
static void put_identifier(ioi_buffer *b, ioi_string name) {
  size_t length;
  char *utf8 = str_utf8(name, &length);
  put(b, "\"", 1);
  for (size_t i = 0; i < length; i++) {
    if (utf8[i] == '"') put(b, "\"", 1);
    put(b, utf8 + i, 1);
  }
  put(b, "\"", 1);
  free(utf8);
}

/* A statement's parameters: each owns its text. */
typedef struct {
  ioi_value *items;
  size_t count, capacity;
} ioi_params;

static void add_param(ioi_params *p, ioi_value v) {
  if (p->count == p->capacity) {
    p->capacity = p->capacity ? p->capacity * 2 : 8;
    p->items = checked(realloc(p->items, p->capacity * sizeof(ioi_value)));
  }
  p->items[p->count++] = v;
}

static void add_text_param(ioi_params *p, ioi_string s) {
  size_t length;
  char *text = str_utf8(s, &length);
  add_param(p, (ioi_value){IOI_TEXT, 0, text, length});
  str_free(&s);
}

static void params_free(ioi_params *p) {
  for (size_t i = 0; i < p->count; i++) free((char *)p->items[i].text);
  free(p->items);
}

/* An item's value as a parameter (services.dart's ItemKind): a number (as text past 2^63 - 1), a
 * tail array's string, or a ;4400 or ;49221 element's. Reads its two values at [*at]. */
static void add_item(ioi_params *p, const uint32_t *arrays, const uint64_t *values, size_t *at, uint32_t next) {
  uint64_t kind = values[(*at)++], value = values[(*at)++];
  switch (kind) {
  case 0:
    if (value <= (uint64_t)INT64_MAX) {
      add_param(p, (ioi_value){IOI_INTEGER, (int64_t)value, NULL, 0});
    } else {
      char digits[24];
      snprintf(digits, sizeof digits, "%llu", (unsigned long long)value);
      add_text_param(p, str_ascii(digits));
    }
    break;
  case 1: add_text_param(p, str_array(arrays[value], next)); break;
  case 2: add_text_param(p, param(value, next)); break;
  default: add_text_param(p, arg(value, next)); break;
  }
}

/* ` WHERE "a" = ? AND "b" = ?` for a HAVING list at [*at]: its count, then (column, item) pairs. */
static void put_having(ioi_buffer *sql, ioi_params *p, uint64_t t, const uint32_t *arrays, const uint64_t *values,
                       size_t *at, uint32_t next) {
  uint64_t pairs = values[(*at)++];
  for (uint64_t i = 0; i < pairs; i++) {
    put_text(sql, i ? " AND " : " WHERE ");
    put_identifier(sql, column_name(t, values[(*at)++], next));
    put_text(sql, " = ?");
    add_item(p, arrays, values, at, next);
  }
}

/* Runs a statement that returns no rows, and counts what it changed. */
static void execute(ioi_buffer *sql, ioi_params *p, uint32_t next) {
  put(sql, "", 1);
  void *rows = adapter->query(db, sql->bytes, p->items, p->count);
  free(sql->bytes);
  params_free(p);
  if (!rows) cassette_fail(826, adapter->error(db), next);
  int status;
  while ((status = adapter->next(rows)) == 1) {
  }
  if (status < 0) cassette_fail(826, adapter->error(db), next);
  adapter->finish(rows);
  last_count = adapter->changes(db);
}

/* Runs a query, leaving row [row]'s columns (from 1) in ;49221 (which it empties first) and how
 * many rows there were in last_count; a statement with no columns counts its changes. */
static void query_into_args(ioi_buffer *sql, ioi_params *p, uint64_t row, uint32_t next) {
  put(sql, "", 1);
  void *rows = adapter->query(db, sql->bytes, p->items, p->count);
  free(sql->bytes);
  params_free(p);
  if (!rows) cassette_fail(826, adapter->error(db), next);
  for (size_t i = 0; i < arg_count; i++) str_free(&args[i].value);
  arg_count = 0;
  int64_t count = 0;
  int status;
  size_t width = adapter->width(rows);
  while ((status = adapter->next(rows)) == 1) {
    if ((uint64_t)++count != row) continue;
    for (size_t i = 0; i < width; i++) {
      ioi_value v;
      adapter->column(rows, i, &v);
      set_arg(i + 1, value_string(v), next);
    }
  }
  if (status < 0) cassette_fail(826, adapter->error(db), next);
  adapter->finish(rows);
  last_count = width ? count : adapter->changes(db);
}

/* The column list of a read or write at [*at]: [t, columns, c...]; a read without columns gets
 * them all. */
static void put_columns(ioi_buffer *sql, uint64_t t, const uint64_t *values, size_t *at, int star, uint32_t next) {
  uint64_t count = values[(*at)++];
  if (!count && star) put_text(sql, "*");
  for (uint64_t i = 0; i < count; i++) {
    if (i) put_text(sql, ", ");
    put_identifier(sql, column_name(t, values[(*at)++], next));
  }
}

static void database(uint32_t service, const uint32_t *scalars, const uint32_t *arrays, const uint64_t *values,
                     uint32_t next) {
  cassette(next);
  ioi_buffer sql = {NULL, 0, 0};
  ioi_params p = {NULL, 0, 0};
  size_t at = 0;
  switch (service) {
  case 16600: {
    uint64_t t = values[at++];
    ioi_string table = table_name(t, next);
    put_text(&sql, "SELECT ");
    put_columns(&sql, t, values, &at, 1, next);
    put_text(&sql, " FROM ");
    put_identifier(&sql, table);
    uint64_t row = values[at++];
    put_having(&sql, &p, t, arrays, values, &at, next);
    query_into_args(&sql, &p, row, next);
    break;
  }
  case 16610:
  case 16620: {
    uint64_t t = values[at++];
    ioi_string table = table_name(t, next);
    uint64_t count = values[at];
    size_t first = at + 1;
    if (service == 16610) {
      put_text(&sql, "INSERT INTO ");
      put_identifier(&sql, table);
      put_text(&sql, " (");
      put_columns(&sql, t, values, &at, 0, next);
      put_text(&sql, ") VALUES (");
      for (uint64_t i = 0; i < count; i++) {
        put_text(&sql, i ? ", ?" : "?");
        add_item(&p, arrays, values, &at, next);
      }
      put_text(&sql, ")");
    } else {
      put_text(&sql, "UPDATE ");
      put_identifier(&sql, table);
      put_text(&sql, " SET ");
      at = first + count;
      for (uint64_t i = 0; i < count; i++) {
        if (i) put_text(&sql, ", ");
        put_identifier(&sql, column_name(t, values[first + i], next));
        put_text(&sql, " = ?");
        add_item(&p, arrays, values, &at, next);
      }
      put_having(&sql, &p, t, arrays, values, &at, next);
    }
    execute(&sql, &p, next);
    break;
  }
  case 16630: {
    uint64_t t = values[at++];
    put_text(&sql, "DELETE FROM ");
    put_identifier(&sql, table_name(t, next));
    put_having(&sql, &p, t, arrays, values, &at, next);
    execute(&sql, &p, next);
    break;
  }
  case 16640: {
    know_tables(next);
    int64_t dropped = 0;
    for (size_t i = 0; i < tables.count; i++) {
      ioi_buffer drop = {NULL, 0, 0};
      ioi_params none = {NULL, 0, 0};
      put_text(&drop, "DROP TABLE ");
      put_identifier(&drop, tables.items[i]);
      execute(&drop, &none, next);
      dropped++;
    }
    forget_schema();
    last_count = dropped;
    break;
  }
  case 16200: {
    ioi_string text = str_array(arrays[0], next);
    size_t length;
    char *utf8 = str_utf8(text, &length);
    str_free(&text);
    put(&sql, utf8, length);
    free(utf8);
    uint64_t count = ick_scalar(scalars[0]);
    for (uint64_t i = 1; i <= count; i++) add_text_param(&p, arg(i, next));
    query_into_args(&sql, &p, ick_scalar(scalars[1]), next);
    forget_schema();
    ick_set_scalar(scalars[0], (uint64_t)last_count);
    break;
  }
  default: ick_set_scalar(scalars[0], (uint64_t)last_count); break;
  }
}

/* ---- Services ---------------------------------------------------------------------------- */

static int petition(uint32_t service, const uint32_t *scalars, uint32_t scalar_count, const uint32_t *arrays,
                    uint32_t array_count, const uint64_t *values, uint32_t value_count, uint32_t next) {
  (void)scalar_count;
  (void)array_count;
  (void)value_count;
  ioi_string value;
  switch (service) {
  case 16001: set_string(arrays[0], env_or_empty("REQUEST_METHOD")); break;
  case 16010: set_string(arrays[0], env_or_empty("QUERY_STRING")); break;
  case 16020: {
    ioi_string name = str_array(arrays[0], next);
    int was = header(name, &value);
    str_free(&name);
    found(scalars[0], arrays[1], was, &value);
    break;
  }
  case 16030: {
    ioi_string name = str_array(arrays[0], next);
    int was = cookie(name, &value);
    str_free(&name);
    found(scalars[0], arrays[1], was, &value);
    break;
  }
  case 16040:
  case 16050: {
    size_t length;
    char *query = NULL;
    const uint8_t *encoded;
    if (service == 16040) {
      ioi_string text = env_or_empty("QUERY_STRING");
      query = str_utf8(text, &length);
      str_free(&text);
      encoded = (const uint8_t *)query;
    } else {
      encoded = form(&length);
    }
    ioi_string name = str_array(arrays[0], next);
    int was = field(encoded, length, name, &value);
    str_free(&name);
    free(query);
    found(scalars[0], arrays[1], was, &value);
    break;
  }
  case 16060: {
    read_body();
    ioi_string s = str_new(body_length);
    for (size_t i = 0; i < body_length; i++) s.units[i] = body[i];
    s.length = body_length;
    set_string(arrays[0], s);
    break;
  }
  case 16100:
    unsent(next);
    status = ick_scalar(scalars[0]);
    break;
  case 16110: {
    unsent(next);
    ioi_string name = str_array(arrays[0], next), v = str_array(arrays[1], next);
    if (!is_token(name) || !is_field_value(v)) ick_fatal(828, next);
    add_header(name, v);
    break;
  }
  case 16120: {
    unsent(next);
    ioi_string name = str_array(arrays[0], next), v = str_array(arrays[1], next);
    if (!is_token(name) || !is_cookie_value(v)) ick_fatal(828, next);
    ioi_string cookie_value = str_new(name.length + v.length + 9);
    memcpy(cookie_value.units, name.units, name.length * sizeof(uint16_t));
    cookie_value.length = name.length;
    cookie_value.units[cookie_value.length++] = '=';
    memcpy(cookie_value.units + cookie_value.length, v.units, v.length * sizeof(uint16_t));
    cookie_value.length += v.length;
    static const char path[] = "; Path=/";
    for (size_t i = 0; i < sizeof path - 1; i++) cookie_value.units[cookie_value.length++] = (uint16_t)path[i];
    str_free(&name);
    str_free(&v);
    add_header(str_ascii("Set-Cookie"), cookie_value);
    break;
  }
  case 16130: {
    unsent(next);
    ioi_string location = str_array(arrays[0], next);
    if (!is_field_value(location)) ick_fatal(828, next);
    status = 303;
    add_header(str_ascii("Location"), location);
    break;
  }
  case 16510: set_string(arrays[0], param(values[0], next)); break;
  case 16511: set_string(arrays[0], arg(values[0], next)); break;
  case 16512: set_arg(values[0], str_array(arrays[0], next), next); break;
  case 16513: set_arg(values[0], param(values[1], next), next); break;
  case 16514: set_arg(values[0], arg(values[1], next), next); break;
  case 16520: ick_fatal((uint32_t)values[0], next); break;
  case 16500: render(&ioi_templates[values[0]], values, next); break;
  case 16200:
  case 16210:
  case 16600:
  case 16610:
  case 16620:
  case 16630:
  case 16640: database(service, scalars, arrays, values, next); break;
  default: return 0;
  }
  return 1;
}

/* ---- Routes (R3, Q113, Q114) ------------------------------------------------------------- */

/* A raw path's segments, up to any ? or #, each percent-decoded; 0 unless it starts with /. */
static int segments_of(ioi_string raw, size_t from, ioi_strings *out) {
  size_t end = from;
  while (end < raw.length && raw.units[end] != '?' && raw.units[end] != '#') end++;
  if (from >= end || raw.units[from] != '/') return 0;
  size_t count = 1;
  for (size_t i = from + 1; i < end; i++) count += raw.units[i] == '/';
  out->items = checked(malloc(count * sizeof(ioi_string)));
  out->count = 0;
  size_t start = from + 1;
  for (size_t i = from + 1; i <= end; i++) {
    if (i < end && raw.units[i] != '/') continue;
    size_t length;
    char *bytes = str_utf8((ioi_string){raw.units + start, i - start}, &length);
    out->items[out->count++] = url_decode((const uint8_t *)bytes, length, 0);
    free(bytes);
    start = i + 1;
  }
  return 1;
}

static int scheme_char(uint16_t c, int first) {
  uint16_t lower = c | 32;
  if (lower >= 'a' && lower <= 'z') return 1;
  return !first && ((c >= '0' && c <= '9') || c == '+' || c == '.' || c == '-');
}

/* Where the scheme and authority of an absolute URL end (scheme://authority), or 0 if it has
 * none; [authority] is where the authority starts. */
static size_t after_authority(ioi_string s, size_t *authority) {
  size_t i = 0;
  while (i < s.length && scheme_char(s.units[i], i == 0)) i++;
  if (i == 0 || i + 3 > s.length || s.units[i] != ':' || s.units[i + 1] != '/' || s.units[i + 2] != '/') return 0;
  *authority = i + 3;
  for (i += 3; i < s.length && s.units[i] != '/' && s.units[i] != '?' && s.units[i] != '#'; i++) {
  }
  return i;
}

/* The request's path segments, decoded: from REQUEST_URI as sent, so that %2F stays inside its
 * segment, or failing that from PATH_INFO. */
static int request_path(ioi_strings *out) {
  ioi_string uri;
  if (env("REQUEST_URI", &uri)) {
    size_t authority, from = after_authority(uri, &authority);
    int ok = segments_of(uri, from, out);
    str_free(&uri);
    return ok;
  }
  ioi_string info = env_or_empty("PATH_INFO");
  size_t count = 1, start = 1;
  if (!info.length) {
    str_free(&info);
    info = str_ascii("/");
  }
  for (size_t i = 1; i < info.length; i++) count += info.units[i] == '/';
  out->items = checked(malloc(count * sizeof(ioi_string)));
  out->count = 0;
  for (size_t i = 1; i <= info.length; i++) {
    if (i < info.length && info.units[i] != '/') continue;
    ioi_string segment = str_new(i - start);
    memcpy(segment.units, info.units + start, (i - start) * sizeof(uint16_t));
    segment.length = i - start;
    out->items[out->count++] = segment;
    start = i + 1;
  }
  str_free(&info);
  return 1;
}

static uint16_t ascii_lower(uint16_t c) { return c >= 'A' && c <= 'Z' ? c + 32 : c; }

/* The Referer's path, when it is a page of this same host. */
static int referer_path(ioi_strings *out) {
  ioi_string referer, host;
  if (!env("HTTP_REFERER", &referer)) return 0;
  if (!env("HTTP_HOST", &host)) {
    str_free(&referer);
    return 0;
  }
  size_t authority = 0, end = after_authority(referer, &authority);
  int same = end && end - authority == host.length;
  for (size_t i = 0; same && i < host.length; i++) {
    same = ascii_lower(referer.units[authority + i]) == ascii_lower(host.units[i]);
  }
  int ok = 0;
  if (same) {
    if (end < referer.length && referer.units[end] == '/') {
      ok = segments_of(referer, end, out);
    } else {
      ioi_string root = str_ascii("/");
      ok = segments_of(root, 0, out);
      str_free(&root);
    }
  }
  str_free(&referer);
  str_free(&host);
  return ok;
}

/* The index of the route [segments] lead to, filling [values] with its parameters, or -1. */
static int32_t match(ioi_strings segments, ioi_strings *values) {
  for (uint32_t i = 0; i < ioi_route_count; i++) {
    const ioi_route *r = &ioi_routes[i];
    values->items = NULL;
    values->count = 0;
    if (r->segment_count < 0) return (int32_t)i;
    if ((size_t)r->segment_count != segments.count) continue;
    int fits = 1;
    for (int32_t j = 0; j < r->segment_count && fits; j++) {
      const ioi_segment *p = &r->segments[j];
      if (p->length >= 0) {
        fits = (size_t)p->length == segments.items[j].length &&
               (p->length == 0 || !memcmp(p->units, segments.items[j].units, (size_t)p->length * sizeof(uint16_t)));
      }
    }
    if (!fits) continue;
    values->items = checked(malloc((segments.count ? segments.count : 1) * sizeof(ioi_string)));
    for (int32_t j = 0; j < r->segment_count; j++) {
      if (r->segments[j].length < 0) values->items[values->count++] = str_copy(segments.items[j]);
    }
    return (int32_t)i;
  }
  return -1;
}

/* Where the request's route starts the program: no route is E440 (a 404 page), and a restricted
 * route whose Referer isn't a page that may link to it is E403. */
static uint32_t start(void) {
  ioi_strings path = {NULL, 0}, values = {NULL, 0};
  int32_t index = request_path(&path) ? match(path, &values) : -1;
  strings_free(&path);
  if (index < 0) ick_fatal(440, 1);
  const ioi_route *route = &ioi_routes[index];
  if (route->allowed_count >= 0) {
    ioi_strings referer = {NULL, 0}, ignored = {NULL, 0};
    int32_t from = referer_path(&referer) ? match(referer, &ignored) : -1;
    strings_free(&referer);
    strings_free(&ignored);
    int allowed = 0;
    for (int32_t i = 0; i < route->allowed_count && from >= 0; i++) allowed |= route->allowed[i] == (uint32_t)from;
    if (!allowed) ick_fatal(403, route->entry);
  }
  params = values.items;
  param_count = values.count;
  return route->entry;
}

static const ick_host ioi_host = {start, petition, prologue};

const ick_host *ick_create_host(void) { return &ioi_host; }
''';
const ioiAdapterHeader = r'''
/* ActiveCassette's adapter interface (R7, Q146), version 1.
 *
 * An adapter connects ActiveCassette to one kind of database. Every Interstates program can use one,
 * whichever compiler built it: ioi-llvm programs call it natively and ioi-dart programs through
 * dart:ffi. SQLite's adapter is built in; any other is a shared library that exports
 * ioi_adapter_entry, and a program uses it for a DATABASE_URL whose scheme is SCHEME when the
 * environment variable IOI_ADAPTER_SCHEME (the scheme in capitals) names the library.
 *
 * ActiveCassette sends standard SQL: identifiers in double quotes, and each value a ? parameter, in
 * order, one statement at a time. An adapter whose database spells either differently translates
 * them.
 *
 * Every string and array ActiveCassette passes in (a url, sql, params and their text, a table) is
 * borrowed for the length of the call only, so an adapter copies whatever it keeps. */
#ifndef IOI_ADAPTER_H
#define IOI_ADAPTER_H

#include <stddef.h>
#include <stdint.h>

#define IOI_ADAPTER_VERSION 1

enum { IOI_NULL = 0, IOI_INTEGER = 1, IOI_TEXT = 2 };

/* A parameter or a column's value. Text is UTF-8, of [length] bytes, not NUL-terminated. */
typedef struct {
  int32_t kind;
  int64_t integer;
  const char *text;
  size_t length;
} ioi_value;

typedef struct {
  /* IOI_ADAPTER_VERSION. */
  uint32_t version;
  /* A connection for [url] (the whole DATABASE_URL), or NULL; error(NULL) then says why. */
  void *(*connect)(const char *url);
  /* Why the last call on [db] failed, as UTF-8, until the next call; NULL when it didn't. */
  const char *(*error)(void *db);
  void (*disconnect)(void *db);
  /* Rows of one text column: the database's tables, in its own order (the order they were made,
   * where it has one). NULL on failure. */
  void *(*tables)(void *db);
  /* Rows of one text column: [table]'s columns, in order. NULL on failure. */
  void *(*columns)(void *db, const char *table);
  /* Runs [sql], one statement, with its [count] parameters. The rows it returns, if any, come from
   * next; a statement that returns none gives rows with none. NULL on failure. */
  void *(*query)(void *db, const char *sql, const ioi_value *params, size_t count);
  /* Moves to the next row: 1 for a row, 0 at the end, -1 on failure (error says why). */
  int (*next)(void *rows);
  /* How many columns each row has, known before the first next. */
  size_t (*width)(void *rows);
  /* Column [i] of the current row, in [out], valid until the next call on [rows]. */
  void (*column)(void *rows, size_t i, ioi_value *out);
  /* Ends the rows, a query's or a statement's. */
  void (*finish)(void *rows);
  /* How many rows the last statement finished on [db] inserted, changed or deleted: 0 for one
   * that changed no rows, such as a CREATE TABLE. */
  int64_t (*changes)(void *db);
} ioi_adapter;

/* What a user adapter's shared library exports. */
const ioi_adapter *ioi_adapter_entry(void);

#endif
''';
const sqliteAdapterC = r'''
/* ActiveCassette's built-in SQLite adapter (R7, Q95, Q99). It is compiled together with the SQLite
 * amalgamation: into ioi-llvm programs, and into the shared library ioi-dart programs load. A
 * DATABASE_URL of sqlite:path opens (or makes) the file at path. */
#include <stdlib.h>
#include <string.h>

#include "ioi_adapter.h"
#include "sqlite3.h"

#ifdef _WIN32
#define IOI_EXPORT __declspec(dllexport)
#else
#define IOI_EXPORT __attribute__((visibility("default")))
#endif

typedef struct {
  sqlite3 *db;
  char *error;
  int64_t changes;
} connection;

typedef struct {
  connection *c;
  sqlite3_stmt *statement;
  int done;
  /* Whether finishing it sets changes: only for the statements a program runs. */
  int counts;
  int64_t total;
} rows;

static char *connect_error;

static void set_error(char **slot, const char *message) {
  free(*slot);
  *slot = NULL;
  if (!message) return;
  size_t n = strlen(message);
  *slot = malloc(n + 1);
  if (*slot) memcpy(*slot, message, n + 1);
}

static void *sqlite_connect(const char *url) {
  set_error(&connect_error, NULL);
  if (strncmp(url, "sqlite:", 7) != 0 || strncmp(url, "sqlite://", 9) == 0) {
    set_error(&connect_error, "a sqlite URL is sqlite:path, such as sqlite:./app.db or sqlite:/srv/app.db");
    return NULL;
  }
  connection *c = calloc(1, sizeof *c);
  if (!c) return NULL;
  if (sqlite3_open_v2(url + 7, &c->db, SQLITE_OPEN_READWRITE | SQLITE_OPEN_CREATE, NULL) != SQLITE_OK) {
    set_error(&connect_error, c->db ? sqlite3_errmsg(c->db) : "out of memory");
    sqlite3_close(c->db);
    free(c);
    return NULL;
  }
  sqlite3_busy_timeout(c->db, 5000);
  /* SQLite opens lazily, so a file that isn't a database would otherwise fail its first statement. */
  if (sqlite3_exec(c->db, "SELECT 1 FROM sqlite_schema LIMIT 0", NULL, NULL, NULL) != SQLITE_OK) {
    set_error(&connect_error, sqlite3_errmsg(c->db));
    sqlite3_close(c->db);
    free(c);
    return NULL;
  }
  return c;
}

static const char *sqlite_error(void *db) { return db ? ((connection *)db)->error : connect_error; }

static void sqlite_disconnect(void *db) {
  connection *c = db;
  sqlite3_close(c->db);
  free(c->error);
  free(c);
}

static void *run(connection *c, const char *sql, const ioi_value *params, size_t count, int counts) {
  set_error(&c->error, NULL);
  sqlite3_stmt *statement;
  const char *tail;
  if (sqlite3_prepare_v2(c->db, sql, -1, &statement, &tail) != SQLITE_OK) {
    set_error(&c->error, sqlite3_errmsg(c->db));
    return NULL;
  }
  while (*tail == ' ' || *tail == '\t' || *tail == '\r' || *tail == '\n' || *tail == ';') tail++;
  if (!statement || *tail) {
    set_error(&c->error, statement ? "one statement at a time" : "no statement");
    sqlite3_finalize(statement);
    return NULL;
  }
  for (size_t i = 0; i < count; i++) {
    int at = (int)i + 1, status;
    switch (params[i].kind) {
    case IOI_INTEGER: status = sqlite3_bind_int64(statement, at, params[i].integer); break;
    case IOI_TEXT:
      status = sqlite3_bind_text64(statement, at, params[i].text, params[i].length, SQLITE_TRANSIENT, SQLITE_UTF8);
      break;
    default: status = sqlite3_bind_null(statement, at); break;
    }
    if (status != SQLITE_OK) {
      set_error(&c->error, sqlite3_errmsg(c->db));
      sqlite3_finalize(statement);
      return NULL;
    }
  }
  rows *r = calloc(1, sizeof *r);
  if (!r) {
    sqlite3_finalize(statement);
    return NULL;
  }
  r->c = c;
  r->statement = statement;
  r->counts = counts;
  r->total = sqlite3_total_changes64(c->db);
  /* A statement that returns no rows runs now, so its changes count even if nobody steps it. */
  if (sqlite3_column_count(statement) == 0) {
    int status = sqlite3_step(statement);
    r->done = 1;
    if (status != SQLITE_DONE && status != SQLITE_ROW) {
      set_error(&c->error, sqlite3_errmsg(c->db));
      sqlite3_finalize(statement);
      free(r);
      return NULL;
    }
  }
  return r;
}

static void *sqlite_query(void *db, const char *sql, const ioi_value *params, size_t count) {
  return run(db, sql, params, count, 1);
}

static void *sqlite_tables(void *db) {
  return run(db,
             "SELECT name FROM sqlite_schema WHERE type = 'table' AND name NOT LIKE 'sqlite\\_%' ESCAPE '\\' ORDER BY rowid",
             NULL, 0, 0);
}

/* The columns SELECT * returns, generated ones included, in its order. */
static void *sqlite_columns(void *db, const char *table) {
  ioi_value name = {IOI_TEXT, 0, table, strlen(table)};
  return run(db, "SELECT name FROM pragma_table_xinfo(?) WHERE hidden <> 1 ORDER BY cid", &name, 1, 0);
}

static int sqlite_next(void *handle) {
  rows *r = handle;
  if (r->done) return 0;
  int status = sqlite3_step(r->statement);
  if (status == SQLITE_ROW) return 1;
  r->done = 1;
  if (status == SQLITE_DONE) return 0;
  set_error(&r->c->error, sqlite3_errmsg(r->c->db));
  return -1;
}

static size_t sqlite_width(void *handle) { return (size_t)sqlite3_column_count(((rows *)handle)->statement); }

static void sqlite_column(void *handle, size_t i, ioi_value *out) {
  sqlite3_stmt *s = ((rows *)handle)->statement;
  int at = (int)i;
  switch (sqlite3_column_type(s, at)) {
  case SQLITE_NULL: *out = (ioi_value){IOI_NULL, 0, NULL, 0}; break;
  case SQLITE_INTEGER: *out = (ioi_value){IOI_INTEGER, sqlite3_column_int64(s, at), NULL, 0}; break;
  default: {
    const unsigned char *text = sqlite3_column_text(s, at);
    *out = (ioi_value){IOI_TEXT, 0, (const char *)text, (size_t)sqlite3_column_bytes(s, at)};
  }
  }
}

static void sqlite_finish(void *handle) {
  rows *r = handle;
  sqlite3_finalize(r->statement);
  /* sqlite3_changes64 keeps the last INSERT, UPDATE or DELETE's count through any other statement. */
  if (r->counts) {
    r->c->changes = sqlite3_total_changes64(r->c->db) == r->total ? 0 : sqlite3_changes64(r->c->db);
  }
  free(r);
}

static int64_t sqlite_changes(void *db) { return ((connection *)db)->changes; }

static const ioi_adapter adapter = {
    IOI_ADAPTER_VERSION, sqlite_connect, sqlite_error,  sqlite_disconnect, sqlite_tables, sqlite_columns,
    sqlite_query,        sqlite_next,    sqlite_width,  sqlite_column,     sqlite_finish, sqlite_changes,
};

IOI_EXPORT const ioi_adapter *ioi_sqlite_adapter(void) { return &adapter; }
